// HasSubscription applies the HasEdge predicate on the "subscription" edge.
func HasSubscription() predicate.RealtimeEvent {
	return predicate.RealtimeEvent(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SubscriptionTable, SubscriptionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSubscriptionWith applies the HasEdge predicate on the "subscription" edge with a given conditions (other predicates).
func HasSubscriptionWith(preds ...predicate.MysekaiBirthdaySubscription) predicate.RealtimeEvent {
	return predicate.RealtimeEvent(func(s *sql.Selector) {
		step := newSubscriptionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RealtimeEvent) predicate.RealtimeEvent {
	return predicate.RealtimeEvent(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RealtimeEvent) predicate.RealtimeEvent {
	return predicate.RealtimeEvent(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RealtimeEvent) predicate.RealtimeEvent {
	return predicate.RealtimeEvent(sql.NotPredicates(p))
}
